// Adapted from mobiletagalog src/lib/progress.tsx:46-55 @ ac003b5 (the ProgressProvider's
// push dependency extracted to a factory over an injected api client plus an onRejected
// hook, so the module runs standalone). Policy: a successful /sync resolves every sent
// event, so poison rows the server rejects still leave the outbox (keeping them would
// resend them, and have them rejected, on every sync forever). Finding F1 accepts that
// drop as a policy but requires it to be a visible decision, so rejected events are
// surfaced through onRejected before they are acknowledged.
export function createPushAdapter(api, onRejected) {
  return async (tokens, events) => {
    const response = await api.sync(tokens.accessToken, events);
    const rejected = new Set(response.rejected);
    if (rejected.size > 0) {
      // Surface the poison rows BEFORE acknowledging them: once acknowledged they are
      // deleted from the outbox, and this report is the only trace they existed (F1).
      onRejected(events.filter((event) => rejected.has(event.id)));
    }
    return {
      progress: response.progress,
      acknowledgedIds: events.map((event) => event.id),
    };
  };
}

