// Adapted from mobiletagalog src/lib/sync.ts:72-105 @ ac003b5 (the coordinator reduced
// to its sync()/runOnce promise chaining over injected dependencies; token refresh and
// generation filtering dropped so the queue behavior stands alone).
export class ProgressSyncCoordinator {
  constructor(dependencies) {
    this.dependencies = dependencies;
    this.tail = Promise.resolve();
  }

  sync() {
    const operation = this.tail.then(() => this.runOnce());
    // The stored tail swallows the rejection: the caller of THIS sync() still sees the
    // error, but the next sync() must chain onto a settled promise or it never runs.
    this.tail = operation.catch(() => undefined);
    return operation;
  }

  async runOnce() {
    const batch = this.dependencies.readOutbox().slice(0, 500);
    if (batch.length === 0) return;
    const result = await this.dependencies.push(batch);
    this.dependencies.commit(result.acknowledgedIds);
  }
}
